/**
 * Bundles packages/recipes for the extension, which loads classic scripts
 * only (the service worker uses importScripts, and MV3 allows no remote
 * code). Writes two generated files:
 *
 *   extension/recipes/vendor/recipes-core.js  every module of core/, each in
 *     its own function scope, in dependency order; exposed as
 *     globalThis.SELECT_TO_AI_RECIPES_CORE (and module.exports for tests)
 *   extension/recipes/vendor/page.js  the in-page script (page-script.js),
 *     run as a content script in the page's isolated world
 *
 *   node scripts/build-recipes.mjs           write the files
 *   node scripts/build-recipes.mjs --check   fail if they are out of date
 *
 * The core is copied as it is: no line of it is changed, only its import
 * and export statements are turned into scope bindings.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const PKG = path.join(root, "packages/recipes");
const CORE = path.join(PKG, "core");
const OUT = path.join(root, "extension/recipes/vendor");

const IMPORT = /^import\s*\{([^}]*)\}\s*from\s*"\.\/([a-z-]+)\.js";\s*$/;
const EXPORT = /^export\s+(?:async\s+)?(?:function\*?|const|let|class)\s+([A-Za-z_$][\w$]*)/;

function parse(name) {
  const src = fs.readFileSync(path.join(CORE, `${name}.js`), "utf8");
  const imports = [];
  const exports = [];
  const lines = src.split("\n").map((line) => {
    if (/^import\b/.test(line)) {
      const m = IMPORT.exec(line);
      if (!m) throw new Error(`${name}.js: an import the bundler does not handle: ${line}`);
      const names = m[1].split(",").map((s) => s.trim()).filter(Boolean);
      if (names.some((n) => /\s/.test(n))) throw new Error(`${name}.js: aliased imports are not handled: ${line}`);
      imports.push({ from: m[2], names });
      return `const { ${names.join(", ")} } = M_${m[2]};`;
    }
    if (/^export\b/.test(line)) {
      const m = EXPORT.exec(line);
      if (!m) throw new Error(`${name}.js: an export the bundler does not handle: ${line}`);
      exports.push(m[1]);
      return line.replace(/^export\s+/, "");
    }
    if (/\bimport\s*\(|\bimport\.meta\b|\brequire\s*\(/.test(line)) throw new Error(`${name}.js: a dynamic import or require: ${line}`);
    return line;
  });
  return { name, imports, exports, body: lines.join("\n") };
}

function order(mods) {
  const byName = new Map(mods.map((m) => [m.name, m]));
  const out = [];
  const state = new Map();
  const visit = (n, trail) => {
    if (state.get(n) === "done") return;
    if (state.get(n) === "busy") throw new Error(`circular import: ${[...trail, n].join(" -> ")}`);
    const m = byName.get(n);
    if (!m) throw new Error(`unknown module ${n}`);
    state.set(n, "busy");
    for (const i of m.imports) visit(i.from, [...trail, n]);
    state.set(n, "done");
    out.push(m);
  };
  for (const m of [...mods].sort((a, b) => a.name.localeCompare(b.name))) visit(m.name, []);
  return out;
}

export function buildCore() {
  const names = fs.readdirSync(CORE).filter((f) => f.endsWith(".js")).map((f) => f.slice(0, -3));
  const mods = order(names.map(parse));
  const all = new Map();
  for (const m of mods) for (const e of m.exports) {
    if (all.has(e)) throw new Error(`${e} is exported by both ${all.get(e)} and ${m.name}`);
    all.set(e, m.name);
  }
  const parts = [
    "// Generated by scripts/build-recipes.mjs from packages/recipes/core. Do not edit.",
    "(function initRecipesCore(root) {",
    '  "use strict";',
  ];
  for (const m of mods) {
    parts.push(`  // ---- core/${m.name}.js`);
    parts.push(`  const M_${m.name} = (function () {\n${m.body}\nreturn { ${m.exports.join(", ")} };\n  })();`);
  }
  parts.push(`  const api = Object.freeze({ ${mods.map((m) => `...M_${m.name}`).join(", ")} });`);
  parts.push("  root.SELECT_TO_AI_RECIPES_CORE = api;");
  parts.push('  if (typeof module !== "undefined" && module.exports) module.exports = api;');
  parts.push('})(typeof globalThis !== "undefined" ? globalThis : this);');
  return `${parts.join("\n")}\n`;
}

export function buildPage() {
  const src = fs.readFileSync(path.join(PKG, "page-script.js"), "utf8");
  const at = src.indexOf("export function pageScript()");
  if (at < 0) throw new Error("page-script.js: no exported pageScript()");
  return `// Generated by scripts/build-recipes.mjs from packages/recipes/page-script.js. Do not edit.\n(${src.slice(at + "export ".length).trim()})();\n`;
}

export function outputs() {
  return { "recipes-core.js": buildCore(), "page.js": buildPage() };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes("--check");
  let stale = 0;
  for (const [file, text] of Object.entries(outputs())) {
    const at = path.join(OUT, file);
    const now = fs.existsSync(at) ? fs.readFileSync(at, "utf8") : null;
    if (now === text) continue;
    if (check) { console.error(`out of date: ${path.relative(root, at)}`); stale++; continue; }
    fs.mkdirSync(OUT, { recursive: true });
    fs.writeFileSync(at, text);
    console.log(`wrote ${path.relative(root, at)}`);
  }
  if (stale) process.exit(1);
}
